def _unescape_pdf_literal(literal):
    def _octal(match):
        return chr(int(match.group(1), 8))

    literal = re.sub(r"\\([0-7]{1,3})", _octal, literal)
    return (
        literal.replace(r"\n", "\n")
        .replace(r"\r", "\r")
        .replace(r"\t", "\t")
        .replace(r"\(", "(")
        .replace(r"\)", ")")
        .replace(r"\\", "\\")
    )


def _text_from_pdf_bytes(pdf_bytes):
