def _ensure_pdftotext():
    if shutil.which("pdftotext"):
        return
    shim_dir = Path(tempfile.mkdtemp(prefix="pdftotext-shim-"))
    shim = shim_dir / "pdftotext"
    script = Path(__file__).with_name("_pdftext.py")
