_ORIG_RUN = subprocess.run


def _unescape_pdf_string(raw):
    def replace(match):
        token = match.group(0)
        if token[1:2].isdigit():
            return bytes([int(token[1:], 8)])
        return {
            b"\\n": b"\n",
            b"\\r": b"\r",
            b"\\t": b"\t",
            b"\\b": b"\b",
            b"\\f": b"\f",
            b"\\(": b"(",
            b"\\)": b")",
            b"\\\\": b"\\",
        }.get(token, token[1:])

    return re.sub(rb"\\[nrtbf()\\]|\\[0-7]{1,3}", replace, raw).decode("latin-1")


def _inflate(data):
    for decoder in (
        lambda blob: zlib.decompress(blob),
        lambda blob: zlib.decompress(blob, -zlib.MAX_WBITS),
    ):
        try:
            return decoder(data)
        except zlib.error:
            continue
    return data


def pdf_to_text(pdf_bytes):
    chunks = []
    for match in re.finditer(rb"stream\r?\n(.*?)endstream", pdf_bytes, re.DOTALL):
        data = match.group(1)
        if data.endswith(b"\r\n"):
            data = data[:-2]
        elif data.endswith(b"\n"):
            data = data[:-1]
        data = _inflate(data)
        for string_match in re.finditer(rb"\((?:\\.|[^\\)])*\)", data):
            chunks.append(_unescape_pdf_string(string_match.group(0)[1:-1]))
    return "\n".join(chunks)


def _run(cmd=None, *args, **kwargs):
    if isinstance(cmd, (list, tuple)) and cmd and cmd[0] == "pdftotext":
