import re
import zlib
from subprocess import CompletedProcess


def unescape_pdf_string(raw):
    def repl(match):
        ch = match.group(1)
        mapping = {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b", b"f": b"\f"}
        if ch in mapping:
            return mapping[ch]
        if ch[:1] in b"01234567":
            return bytes([int(ch, 8)])
        return ch

    unescaped = re.sub(rb"\\([nrtbf]|[0-7]{1,3}|.)", repl, raw)
    return unescaped.decode("latin-1")


def extract_text(pdf_bytes):
    texts = []
    for match in re.finditer(rb"stream\r?\n(.+?)endstream", pdf_bytes, re.DOTALL):
        data = match.group(1)
        if data.endswith(b"\r\n"):
            data = data[:-2]
        elif data.endswith(b"\n"):
            data = data[:-1]
        try:
            data = zlib.decompress(data)
        except zlib.error:
            pass
        for raw, _op in re.findall(rb"\(((?:\\.|[^\\)])*)\)\s*(Tj|')", data):
            texts.append(unescape_pdf_string(raw))
        for array in re.findall(rb"\[((?:(?!\s*TJ).)*)\]\s*TJ", data):
            for raw in re.findall(rb"\(((?:\\.|[^\\)])*)\)", array):
                texts.append(unescape_pdf_string(raw))
    return "\n".join(texts)


def run_pdftotext(command, kwargs):
    args = [str(part) for part in command[1:] if not str(part).startswith("-")]
    input_path = args[0]
    with open(input_path, "rb") as handle:
        text = extract_text(handle.read())
    as_text = bool(kwargs.get("text") or kwargs.get("universal_newlines"))
    stdout = text if as_text else text.encode("utf-8")
    stderr = "" if as_text else b""
    return CompletedProcess(command, 0, stdout=stdout, stderr=stderr)
